#!/usr/bin/env python3
"""Builds assets/bazaar_tree.json (category -> family -> [product ids]) from the live bazaar product list.
The Hypixel API has no categories, so the families come from the rules below (modelled on the in-game bazaar). Re-run when new items appear;
anything no rule matches is shown under Oddities > Other by the app itself."""
import json, re, sys, urllib.request, os
ids = sorted(json.load(urllib.request.urlopen("https://api.hypixel.net/v2/skyblock/bazaar"))["products"])
R = lambda p: re.compile(p)
# (category, family, regex) -- first match wins
RULES = [
 ("Oddities","Enchanted Books",R(r"^ENCHANTMENT_")),
 ("Oddities","Shards",R(r"^SHARD_")),
 ("Farming","Wheat & Seeds",R(r"^(ENCHANTED_)?(WHEAT|SEEDS|BREAD|HAY_(BALE|BLOCK)|HAY_BLOCK)$|^BOX_OF_SEEDS$|^TIGHTLY_TIED_HAY_BALE$|^FINE_FLOUR$|^SALTED_SUNFLOWER_SEEDS$|^ENCHANTED_HAY")),
 ("Farming","Carrot",R(r"CARROT")),
 ("Farming","Potato",R(r"POTATO|^HASHBROWN$")),
 ("Farming","Pumpkin",R(r"PUMPKIN|^GLOOMGOURD$|^TURBO_GOURD|^ENCHANTED_TURBO_GOURD$")),
 ("Farming","Melon",R(r"MELON")),
 ("Farming","Mushroom",R(r"MUSHROOM|^MYCEL|^ENCHANTED_MYCELIUM|^BROWN_MUSHROOM|^SHROOM|^FEASTFUNGUS$|^MARSHROOM$|^ZOMBUD$")),
 ("Farming","Cocoa Beans",R(r"COCOA|COOKIE$|^INK_SACK:3$|^CHOCO|^CHOCOLATE|^DARK_CANDY$|^REFINED_DARK_CACAO")),
 ("Farming","Cactus",R(r"CACTUS|^PRICKLY|^POTTED_CACTUS")),
 ("Farming","Sugar Cane",R(r"SUGAR|PAPER|^CANE_KNOT$|^ROCK_CANDY$")),
 ("Farming","Nether Wart",R(r"NETHER_STALK|^WARTY$")),
 ("Farming","Raw Chicken, Feather & Egg",R(r"CHICKEN|FEATHER|^(ENCHANTED_|SUPER_)?EGG$|^OMEGA_EGG$|^FRIED_FEATHER$")),
 ("Farming","Pork, Beef & Mutton",R(r"PORK|BEEF|MUTTON|^FATEFUL_STINGER$")),
 ("Farming","Rabbit",R(r"^(ENCHANTED_)?RABBIT|^FACTION_RABBIT")),
 ("Farming","Leather & Wool",R(r"LEATHER|WOOL|^BLACK_WOOLEN_YARN$|^LUXURIOUS_SPOOL$")),
 ("Farming","Honey",R(r"HONEY|^ROYAL_JELLY$|^BEE_SALIVA$|^POT_OF_HONEYCOMB")),
 ("Farming","Flowers & Compost",R(r"SUNFLOWER|MOONFLOWER|WILD_ROSE|COMPOST|DANDELION|POPPY|^RED_ROSE$|^YELLOW_FLOWER$|^DOUBLE_PLANT$|^HELIANTHUS$|^CONDENSED_HELIANTHUS$|^LONELILY|^SOGGYBUD|^CREAMBLOOM|^STOPLIGHT|^DUSKBLOOM|^NOCTILUME|^SHADEVINE|^SCOURROOT|^PHANTOMLEAF|^MAGIC_JELLYBEAN|^CHOCONUT|^THORNSHADE|^GLASSCORN|^GODSEED|^DEAD_PLANT|^PLANT_MATTER|^CROPIE|^SQUASH|^CROPSHOT|.*GARDEN_CHIP$|^DUNG$|^SLUDGE_JUICE$|^TASTY_|^VERMIN_|^PESTHUNTING|^PLOT_ERASER|^OVERFLOWING_TRASH|^JACOB|^FARMING_|^BURROWING_SPORES$|^FLORAL_GELATIN$|^FLOWERING_BOUQUET$|^VISITORS_GRATITUDE$|^TURBO_|^MORNING_DEW$|^MOONDEW$|^ETHEREAL_VINE$|^STARTLEVINE$|^TIMESTALK$|^VINESAP|^ENCHANTED_VINESAP|^FERMENTO|^CONDENSED_FERMENTO|^LUSH|^ENCHANTED_LUSH|^BLASTBERRY|^BLESSED_FRUIT$|^SHELLFRUIT$|^BOTROOT$|^DEEP_ROOT$|^CORLEONITE$|^SPELL_POWDER$|^BAYOU|^BUDGET_HOPPER$|^ENCHANTED_HOPPER$|^COMPACTED_|^CONDENSED_WATER|^WATER_LILY$|^ENCHANTED_WATER_LILY$|^LILY_PAD")),
 ("Mining","Cobblestone & Stone",R(r"COBBLE|^HARD_STONE$|^ENCHANTED_HARD_STONE$|^CONCENTRATED_STONE$|^BULKY_STONE$|^FIGSTONE$|^ENCHANTED_FLINT$|^FLINT$|^GRAVEL$|^ENDER_STONE$|^ENCHANTED_ENDSTONE|^ENDSTONE|^ENCHANTED_CLAY|^CLAY_BALL$|^VOLCANIC_ROCK$|^HARDENED_WOOD$|^ROCK_GEMSTONE$")),
 ("Mining","Coal",R(r"COAL|CHARCOAL|^SULPHURIC")),
 ("Mining","Iron",R(r"^(ENCHANTED_)?IRON|^IRON_INGOT$")),
 ("Mining","Gold",R(r"^(ENCHANTED_)?GOLD(_BLOCK)?$|^GOLD_INGOT$|^ENCHANTED_GOLD")),
 ("Mining","Diamond",R(r"^(ENCHANTED_|REFINED_|RARE_)?DIAMOND(_BLOCK)?$|^DIAMOND_|^ENCHANTED_DIAMOND|^ESSENCE_DIAMOND$|^GIANT_FRAGMENT_DIAMOND$")),
 ("Mining","Lapis",R(r"LAPIS")),
 ("Mining","Emerald",R(r"^(ENCHANTED_)?EMERALD|^JADERALD$")),
 ("Mining","Redstone",R(r"REDSTONE")),
 ("Mining","Quartz",R(r"QUARTZ")),
 ("Mining","Obsidian",R(r"OBSIDIAN(?!_TABLET)")),
 ("Mining","Glowstone",R(r"GLOWSTONE|^HIGHLITE$|^SPOTLITE$")),
 ("Mining","Ice & Snow",R(r"ICE|SNOW(?!GLOBE)|^FROZEN_SCUTE$|^BLUE_ICE")),
 ("Mining","Netherrack & Sand",R(r"NETHERRACK|^(ENCHANTED_)?(RED_)?SAND|^SAND:1$|^ENCHANTED_RED_SAND|^SULPHUR|^ENCHANTED_SULPHUR|^LAVA|^MAGMA_BUCKET$|^ENCHANTED_LAVA")),
 ("Mining","Mining Materials",R(r"MITHRIL|TITANIUM|^PURE_MITHRIL|^REFINED_(MINERAL|MITHRIL)|^STARFALL$|^PETRIFIED_STARFALL$|^SEARING_STONE$|^GOBLIN_EGG|^GEMSTONE_MIXTURE$|^GLOSSY_GEMSTONE$|^GLACITE|^ENCHANTED_GLACITE|^TUNGSTEN|^UMBER|^REFINED_TUNGSTEN|^REFINED_UMBER|^ENCHANTED_TUNGSTEN|^ENCHANTED_UMBER|^DWARVEN|^FUEL_TANK$|^GOLDEN_PLATE$|^PERFECT_PLATE$|^DIAMONITE$|^TREASURITE$|^AMBER_MATERIAL$|^REFINED_AMBER$|^SALMON_OPAL$|^IRIDIUM$|^ONYX$|^MOONSTONE$|^SUNSTONE$|^GLEAMING_CRYSTAL$|^SORROW$|^VOLTA$|^OIL_BARREL$|^CORRUPTED_FRAGMENT$|^FOSSIL|.*_FOSSIL$|^ESSENCE_FOSSIL$|^SPINE|^HELIX|^MOLTEN|^SALT_CUBE$|^SEA_BRINE|^ENTROPY|^ELECTRON|^ROBOTRON|^SYNTHETIC_HEART$|^SUPERLITE|^CONTROL_SWITCH$|^FTX_|^BEZOS$|^SIL_EX$|^ASCENSION_ROPE$|^LESSER_SOUL|^SOULFLOW|^RAW_SOULFLOW|^ENCHANTED_COMPACTOR|^DRILL_ENGINE$|^MITHRIL_INFUSION$|^AUTO_SMELTER$|^PLASMA|^KELVIN|^SUBZERO|^FUEL_GABAGOOL|^HEAVY_GABAGOOL|^HYPERGOLIC|^CRUDE_GABAGOOL|^VERY_CRUDE|^MAGMAG$|^GOLDEN_BALL$|^GOLDEN_TOOTH$|^TRANSMISSION_TUNER$|^OVERCLOCKER_3000$|^ENDSTONE_GEODE$|^TITANIUM_TESSERACT$")),
 ("Mining","Gemstones",R(r"^(ROUGH|FLAWED|FINE|FLAWLESS|PERFECT)_.*_GEM$|^MANGROVE_GEM$")),
 ("Combat","Rotten Flesh & Zombie",R(r"ROTTEN_FLESH|^REVENANT|^UNDEAD|^ESSENCE_UNDEAD|^FOUL_FLESH|^PREMIUM_FLESH|^HEALING_TISSUE|^SEVERED|^DIGESTED|^FESTERING|^WEREWOLF|^WOLF_TOOTH|^WEAK_WOLF|^HALF_EATEN|^TENTACLE_MEAT|^DEVOURER$")),
 ("Combat","Bone & Skeleton",R(r"BONE(?!_MEAL)|^(ENCHANTED_)?BONE_MEAL|^SPIRIT_BONE|^STURDY_BONE|^FLEXBONE|^FLEXBONE")),
 ("Combat","String & Spider",R(r"STRING|SPIDER|TARANTULA|^ARACHNE|^ENCHANTED_SPIDER|^MITE_GEL|^MIXED_MITE|^WEBBED|^SILVER_FANG|^ESSENCE_SPIDER|^ENSNARED_SNAIL|^SUBLIME_SILK$")),
 ("Combat","Gunpowder & Creeper",R(r"GUNPOWDER|^SULPHUR$|^SUPERBOOM|^GIANT_FRAGMENT_LASER|^TOXIC_ARROW|^TWILIGHT_ARROW|^ARROW_BUNDLE")),
 ("Combat","Ender",R(r"ENDER|EYE_OF_ENDER|^ABSOLUTE_ENDER|^ENDERMAN|^HAZMAT_ENDERMAN|^TESSELLATED|^SUMMONING_EYE|^REMNANT|^ENDSTONE_IDOL$|^END_STONE_SHULKER$|^NULL_|^SPECTRE|^FEL_PEARL$|^GAZING_PEARL$|^HEAVY_PEARL$|^PRECIOUS_PEARL$|^ENCHANTED_ENDER")),
 ("Combat","Nether (Ghast, Blaze, Magma)",R(r"GHAST|BLAZE|MAGMA(?!_BUCKET)|^FLAMES$|^HOT_STUFF$|^INFERNO|^ESSENCE_CRIMSON|^MILLENIA|^MUTATED_BLAZE|^HOT_|^SCORCHED|^BURNING_EYE|^RED_NOSE$|^KUUDRA|^LUMP_OF_MAGMA|^MOOGMA|^PYROCLASTIC|^REKINDLED|^SULPHUR_ORE|^ASHWREATH|^BRIMSTONE|^FLAMING_HEART$|^FIRE_IN_A_BOTTLE|^WHIPPED_MAGMA|^LAVA_SHELL|^CHEESE_FUEL$|^SINGED|^AMALGAMATED|^NETHER_STAR|^CORRUPTED_NETHER|^MOLTEN_CUBE")),
 ("Combat","Slime",R(r"SLIME|^ENCHANTED_SLIME|^COMPACT_OOZE$|^JELLY$|^MAGIC_MUSHROOM_SOUP")),
 ("Combat","Wither & Dragon",R(r"WITHER|DRAGON|^ESSENCE_WITHER|^ESSENCE_DRAGON|^SUPERIOR_FRAGMENT|^STRONG_FRAGMENT|^YOUNG_FRAGMENT|^OLD_FRAGMENT|^UNSTABLE_FRAGMENT|^WISE_FRAGMENT|^PROTECTOR_FRAGMENT|^HOLY_FRAGMENT|^NECROMANCER|^PRECURSOR|^GIANT_TOOTH|^HOLY|^DARK_QUEENS")),
 ("Combat","Dungeons",R(r"DUNGEON|MASTER_STAR|^BONZO|^SCARF|^LIVID|^DIVER|^MIMIC|^THORN_|^SPIRIT_|^ESSENCE_|^BOOK_OF_STATS|^THE_ART|^FUMING|^RECOMBOBULATOR|^SADAN|^JERRY|^CHAIN_END|^BOB_OMB|^FIGHTING_BOOSTER|^FIFTH|^HAMSTER|^SPIDER_CATALYST|^.*_CATALYST$|^IMPLOSION|^SHADOW_WARP|^WITHER_SHIELD|^ASCENSION|^FAKE_SHURIKEN|^INFLATABLE_JERRY|^MOBY|^ARCHITECT")),
 ("Woods & Fishes","Logs",R(r"LOG|^MANGROVE|^TENDER_WOOD|^ENCHANTED_TENDER_WOOD|^FIG|^MOIL|^TOIL|^HELIX_LOG|^FORESTS_FAVOR|^SWEEP_BOOSTER|^FORAGING|^WOOD_SINGULARITY|^GENERATOR_UPGRADE|^ACACIA_BIRDHOUSE|^TRUNK_POLISH|^FLY_SWATTER|^HUNTING|^LOCUST|^ESSENCE_FOREST|^ESSENCE_SAFARI|^LARGE_WALNUT|^WALNUT|^LUMINO|^EXTREMELY_MILD|^BOTTLED_MISCHIEF")),
 ("Woods & Fishes","Fishing & Sea",R(r"FISH|SALMON|CLOWNFISH|PUFFERFISH|^RAW_FISH|^ENCHANTED_COOKED|^MAGMA_FISH|^INK|^ENCHANTED_INK|^OCTOPUS|^SHARK|^.*SHARK_TOOTH$|^GREAT_WHITE|^NURSE|^TIGER|^BLUE_SHARK|^ENCHANTED_SHARK|^PITCHIN_KOI|^TITANOBOA|^TURTLELLINI|^MAGMA_URCHIN|^CAN_OF_WORMS|^WORM|^CHUM|^FULL_CHUM|^EMPTY_CHUM|^CHYME|^GLOWY_CHUM|^BRINE_TONIC|^SQUEAKY|^ALLIGATOR|^GILL|^FROG|^BUCKET_OF_FROGSPAWN|^GIANT_FROG|^LARGE_FROG|^MEDIUM_FROG|^SMALL_FROG|^MOUND_OF_SEAGRASS|^SEA_LUMIES|^ENCHANTED_SEA_LUMIES|^ENCHANTED_SPONGE|^SPONGE|^ENCHANTED_WET_SPONGE|^PRISMARINE|^ENCHANTED_PRISMARINE|^VIBRANT_CORAL|^SHELLFRUIT|^SCUTTLER|^SEVERED_PINCER|^OCEANDY|^TROUBLED_BUBBLE|^DEEP_SEA|^.*_WATER_ORB$|^WATER_ORB$|^BAYOU|^RUSTY_ANCHOR|^OLD_LEATHER_BOOT|^UGLY|^CRYSTALIZED_MOONLIGHT|^PUFFERCLOUD|^CALCIFIED|^SEARED_ESCARGOT|^SCORCHED_CRAB|^FISHING|^.*_BAIT$|^FISH_BAIT|^MINNOW|^WET_WATER|^WET_BOOK|^ISOPOD|^DISPLACED|^FROZEN_BAUBLE|^LAVA_WATER_ORB|^SOUL_FRAGMENT$|^SEA_BRINE|^SNOOZLING|^YOGGIE|^TITANIC|^TIGHTLY")),
 ("Oddities","Pet Items & Cakes",R(r"^PET_|^SUPREME_CHOCOLATE|^REHEATED|^SKYMART|^MIRIA|^STARLYN|^AGATHA|^ELECTRON_TRANSMITTER|^GRIFFIN|^BRAIDED_GRIFFIN")),
 ("Oddities","Boosters, Cookies & Bottles",R(r"BOOSTER|COOKIE|EXP_BOTTLE|^COLOSSAL|^GRAND|^TITANIC_EXP|^BAZAAR|^ENCHANTED_CHEST|.*_ENCHANTED_CHEST$|^TOOL_EXP|^MINION|^COMPACTOR|^SUPER_COMPACTOR|^DWARVEN_COMPACTOR|^GENERATOR|^HYPER_CATALYST|^CATALYST|^CELESTIAL|^HYPERCHARGE|^FREE_WILL|^BOOKWORM|^POLARVOID|^JALAPENO|^PESTHUNTING")),
 ("Oddities","Gifts, Candy & Events",R(r"GIFT|CANDY|^SPOOKY|^WINTER|^TERRY|^POCKET|^JERRY_BOX|^PARTY|^SANTA|^PRESUMED|^BOUNCY|^GIANT_BOUNCY|^HORSEMAN|^RED_SCARF$|^CANDYCOMB$|^GOLD_BOTTLE|^FROGCOIN|^FRESHLY_MINTED|^BLOOD_|^UNLUCKY|^RUSTY_COIN|^TREASURE|^SHINY_PRISM|^BEJEWELED|^MAGIC_TOP_HAT|^LUCKY_DICE|^STOCK_OF_STONKS|^BEADY|^GOLDEN_BOUNTY|^GOLDEN_FRAGMENT|^DARK_ORB|^FURBALL|^MANDRAA|^OBSIDIAN_TABLET|^BEATING_HEART|^ECCENTRIC|^GEOMETRIC|^CUP_OF_BLOOD|^SLEEPY_HOLLOW|^SQUEAKY_TOY|^BLUE_RING|^BROKEN_RADAR|^BRONZE_BOWL|^BUBBA|^BUSTED|^CAPSAICIN|^CHEESEBITE|^DAEDALUS|^DAYSWITCH|^NIGHTSWITCH|^DERELICT|^DISTANT_ECHO|^DIVAN|^EXALTED|^LUSHLILAC|^PRIME_LUSH|^REFINED_BOTTLE|^SCORCHED_BOOKS|^SIGNAL_ENHANCER|^SOLAR_PANEL|^TITANIUM_TESS|^UNALLOYED|^VITAMIN|^GOLDEN_|^LOTUS|^GLACIAL|^GLACITE_JEWEL|^MIDAS_JEWEL|^MOONGLADE|^ARCHITECT|^AOTE_STONE|^JERRY_STONE|^DRAGON_|^LARGE_ENCHANTED|^DARK_BAIT")),
]
tree, left = {}, []
for i in ids:
    for cat, fam, rx in RULES:
        if rx.search(i):
            tree.setdefault(cat, {}).setdefault(fam, []).append(i); break
    else:
        left.append(i)
for cat, fams in tree.items():
    for f in fams: fams[f].sort()
# enchanted books: one family per enchant, with its levels as items
eb = tree.get("Oddities", {}).pop("Enchanted Books", [])
books = {}
for i in eb:
    base = re.sub(r"_\d+$", "", i[len("ENCHANTMENT_"):])
    books.setdefault(base, []).append(i)
tree.setdefault("Enchantments", {}).update({k: sorted(v, key=lambda s: int(re.search(r"_(\d+)$", s).group(1)) if re.search(r"_(\d+)$", s) else 0) for k, v in sorted(books.items())})
tree.setdefault("Oddities", {})["Other"] = left
out = os.path.join(os.path.dirname(__file__), "..", "assets", "bazaar_tree.json")
json.dump(tree, open(out, "w"), separators=(",", ":"))
print({c: {f: len(v) for f, v in fs.items()} if c != "Enchantments" else len(fs) for c, fs in tree.items()}, file=sys.stderr)
print("unmatched:", len(left), left[:60], file=sys.stderr)
